        option?.onSelected?.();
    };

    const handleOnCloseMenu = () => {
        selectedOptionIndexRef.current = -1;
        closeMenu();
    };

    return (
        <View style={[styles.pb4]}>
            <Button
                onPress={openMenu}
                ref={buttonRef}
